import{_ as e,o as t,c as r,a2 as l}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"热键设置","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/hotkeys-page.md","filePath":"zh-CN/user-guide/settings/hotkeys-page.md","lastUpdated":1787586465000}'),s={name:"zh-CN/user-guide/settings/hotkeys-page.md"};function a(n,o,c,i,d,g){return t(),r("div",null,[...o[0]||(o[0]=[l('<h1 id="热键设置" tabindex="-1">热键设置 <a class="header-anchor" href="#热键设置" aria-label="Permalink to &quot;热键设置&quot;">​</a></h1><p>热键设置页面集中管理 Lertaro 的所有全局唤起按键、应用内导航快捷键、插件动作快捷方式以及前台进程过滤规则。页面顶部包含三个标签页：<strong>全局</strong>、<strong>插件动作</strong>与<strong>进程黑名单</strong>。</p><h2 id="_1-全局-global" tabindex="-1">1. 全局（Global） <a class="header-anchor" href="#_1-全局-global" aria-label="Permalink to &quot;1. 全局（Global）&quot;">​</a></h2><h3 id="全局快捷键分组" tabindex="-1">全局快捷键分组 <a class="header-anchor" href="#全局快捷键分组" aria-label="Permalink to &quot;全局快捷键分组&quot;">​</a></h3><ul><li><strong>显示/隐藏快速搜索</strong>：专属按键录制框。支持录制为<strong>单键双击模式</strong>（默认双击 <code>Ctrl</code>，亦可设为双击 <code>Alt</code> 或 <code>Shift</code>），或录制为<strong>常规组合键</strong>（如 <code>Alt+Space</code>、<code>Win+Space</code> 等）。</li><li><strong>全屏应用聚焦时仍然响应</strong>：复选框（默认关闭）。开启后，即使前台有独占全屏程序（如全屏游戏或视频），Lertaro 依然会响应快捷键呼出搜索框；保持关闭则自动放行按键不抢占焦点。</li><li><strong>快速跳转（Quick Jump）</strong>：默认 <code>Ctrl+G</code>。在各类文件对话框中按下即可直接跳转到最近在文件管理器中浏览过的目录。</li></ul><h3 id="功能按键分组" tabindex="-1">功能按键分组 <a class="header-anchor" href="#功能按键分组" aria-label="Permalink to &quot;功能按键分组&quot;">​</a></h3><p>页面提供了一系列独立的按键录制控件，支持任意单键或组合键录制：</p><ul><li><strong>选中下一项 / 上一项</strong>：默认 <code>Ctrl+N</code> / <code>Ctrl+P</code>（与方向键 <code>↓</code> / <code>↑</code> 等效）。</li><li><strong>跳转结果修饰键</strong>：默认 <code>Ctrl</code>，配合数字键 <code>1</code>–<code>9</code> 即可在快速窗口中直达前 9 项结果。</li><li><strong>打开动作菜单</strong>：默认 <code>Ctrl+O</code>（与方向键 <code>→</code> 等效）。</li><li><strong>从选中项补全搜索词</strong>：默认 <code>Ctrl+Tab</code>。</li><li><strong>QuickLook 即时预览</strong>：默认 <code>Alt+P</code>。</li><li><strong>上/下一条关键字历史</strong>：默认 <code>Alt+Up</code> / <code>Alt+Down</code>。</li><li><strong>删除当前关键字历史</strong>：默认 <code>Ctrl+Delete</code>。</li><li><strong>打开完整搜索主窗口</strong>：默认 <code>Ctrl+F</code>。</li><li><strong>打开发送窗口（LocalSend）</strong>：默认 <code>Ctrl+S</code>。</li><li><strong>保持窗口不消失（钉住）</strong>：默认 <code>Ctrl+T</code>。</li><li><strong>呼出/关闭快速面板</strong>：默认 <code>Ctrl+F2</code>。</li></ul><h3 id="快速导航鼠标触发分组" tabindex="-1">快速导航鼠标触发分组 <a class="header-anchor" href="#快速导航鼠标触发分组" aria-label="Permalink to &quot;快速导航鼠标触发分组&quot;">​</a></h3><ul><li><strong>在空白处双击左键</strong>：复选框（默认开启）。在桌面或文件资源管理器空白处双击弹出快速导航菜单。</li><li><strong>在空白处点击中键</strong>：复选框（默认开启）。在桌面、文件资源管理器或文件选择对话框中点击鼠标中键弹出快速导航菜单。</li></ul><h2 id="_2-插件动作-plugin-actions" tabindex="-1">2. 插件动作（Plugin Actions） <a class="header-anchor" href="#_2-插件动作-plugin-actions" aria-label="Permalink to &quot;2. 插件动作（Plugin Actions）&quot;">​</a></h2><p>各插件注册的专属动作快捷键（例如内置的文件操作：复制路径 <code>Ctrl+Shift+C</code>、剪切 <code>Ctrl+X</code>、复制 <code>Ctrl+C</code>、粘贴 <code>Ctrl+V</code>、删除 <code>Delete</code>、彻底删除 <code>Shift+Delete</code> 等）均汇集于此。</p><ul><li><strong>分组查看</strong>：按注册动作的来源插件清晰分组。</li><li><strong>独立重录</strong>：每个动作均配有专属的按键录制框，点击即可按下新按键进行覆盖绑定。</li></ul><h2 id="_3-进程黑名单-process-blacklist" tabindex="-1">3. 进程黑名单（Process Blacklist） <a class="header-anchor" href="#_3-进程黑名单-process-blacklist" aria-label="Permalink to &quot;3. 进程黑名单（Process Blacklist）&quot;">​</a></h2><p>用于配置特定前台应用程序的静默放行机制。当黑名单中的程序处于系统前台聚焦状态时，Lertaro 会完全放行所有全局热键与鼠标触发手势，绝不进行拦截。</p><ul><li><strong>不区分大小写</strong>：添加 <code>game.exe</code> 或 <code>game</code> 均可生效。</li><li><strong>单条添加</strong>：在单条输入框中输入进程名，点击<strong>添加进程</strong>按钮。</li><li><strong>批量管理</strong>：支持点击<strong>生成文本</strong>将当前黑名单导出为多行文本，或在多行文本框中直接粘贴编辑后点击<strong>应用到列表</strong>进行一键批量导入。</li><li><strong>文件对话框安全豁免</strong>：即使某个程序处于黑名单中，当它弹出系统文件选择对话框时，Lertaro 的内嵌搜索与鼠标快速导航依然会被安全放行，确保文件选取效率不受影响。</li></ul>',16)])])}const p=e(s,[["render",a]]);export{u as __pageData,p as default};
